window.DOSIK=window.DOSIK||{};DOSIK["sw_practice"]={"1":[{"t":"tree","title":"사회복지실천의 목적","root":"사회복지실천","branches":[["개인","개인의 문제해결과 대처능력을 향상한다"],["환경","개인을 사회자원, 서비스, 기회를 제공해주는 환경체계와 연결한다"],["기관","다양한 사회복지기관이나 조직의 효과적이고 효율적인 운영을 촉진한다"],["사회정책","사회정책의 개발과 향상에 기여한다"]]},{"t":"tree","title":"사회복지의 역사적 영향","root":"사회복지의 발달","branches":[["종교","사회복지가 종교와 밀접한 관련 하에 전개되도록 하였다"],["전문 사회복지","전문 사회복지의 시작을 촉발하였다"],["미시적 사회사업","거시적인 사회정책보다는 미시적인 사회사업 위주로 발전하게 하였다"],["인식","사람들이 사회복지를 구호사업 또는 자선사업과 같은 것으로 인식하게 하였다"]]},{"t":"tree","title":"자선조직협회","root":"자선조직협회","branches":[["등장","민간 사회복지기관의 활동을 체계적으로 조정하기 위해 등장하였다"],["이론","적자생존에 기반한 사회진화론을 구빈의 이론적 기반으로 삼았다"],["등록체계","과학적이고 적절한 자선활동을 수행하기 위해 클라이언트 등록체계를 실시하였다"],["의의","자선조직협회 활동은 개별사회사업의 초석이 되었다"]]}],"3":[{"t":"vs","title":"평등권·자유권·평화권","cols":[{"name":"평등권","items":["국가의 적극적 책임과 의무를 강조하는 것으로 사회보장의 권리를 의미한다","경제적, 사회적, 문화적 권리이다"]},{"name":"자유권","items":["국가의 통치와 간섭으로부터 자유를 보장하기 위한 권리이다","국가가 반드시 보호해 주어야 하는 권리이다","시민적, 정치적 권리이다"]},{"name":"평화권","items":["국가들 간의 연대와 단결의 권리이다"]}]},{"t":"def","term":"천부성","text":"인간이 세상에 태어나면서부터 존엄성을 가지고 태어났다는 의미이다"}],"4":[{"t":"tree","title":"강점관점","root":"강점관점","branches":[["자원","어떤 환경이든 자원은 존재한다고 본다"],["강점","모든 클라이언트는 강점이 있다고 본다"],["주체","클라이언트를 선택과 결정의 주체로 본다"],["개입의 초점","가능성에 있다"]]},{"t":"tree","title":"임파워먼트","root":"클라이언트를 보는 관점","branches":[["협력","클라이언트가 원하는 변화를 위해 양자 간 협력적 관계를 형성한다"],["소비자","서비스에 대한 권리를 가진 소비자로 본다"],["파트너","경험과 역량을 가진 원조과정의 파트너로 본다"],["참여","클라이언트의 참여를 중시하고 자기결정권을 강조한다"]]},{"t":"table","title":"체계이론의 체계","head":["체계","내용"],"rows":[["클라이언트체계","부모가 자녀의 문제로 상담을 요청한 경우, 부모"],["표적체계","법원 명령으로 본인 의사와 관계없이 문제행동 감소를 위해 사회복지사에게 의뢰된 청소년"],["행동체계","사회복지사의 활동 목적을 달성하기 위해 공동으로 노력하는 모든 체계"],["변화매개체계","클라이언트의 문제를 해결하기 위해 노력하는 사회복지사와 사회복지기관"]]}],"5":[{"t":"tree","title":"전문적 관계의 특성","root":"전문적 관계","branches":[["목적","사회복지사와 클라이언트가 합의하여 목적을 설정한다 · 상호합의한 목적을 가진다"],["시간","시간 제한적이다"],["대상","클라이언트를 위한 것이다 · 클라이언트의 문제와 욕구가 중심이 된다"],["권위","사회복지사는 전문성에 바탕을 둔 권위를 가진다"],["기관","사회복지사는 소속된 기관의 특성에 영향을 받는다"]]},{"t":"tree","title":"수용","root":"수용","branches":[["이해","클라이언트를 있는 그대로 이해한다"],["감정","클라이언트의 부정적인 감정도 받아들인다"],["선입관","편견이나 선입관을 줄여나가면 수용에 도움이 된다"],["안도감","클라이언트가 안도감을 갖게 하여 현실적인 방법으로 문제 대처를 할 수 있도록 돕는다"]]}],"6":[{"t":"tree","title":"면접의 특성","root":"면접","branches":[["관계","사회복지사와 클라이언트 사이의 특정한 역할 관계가 있다"],["맥락","특정 상황이나 맥락에 관련하여 이루어진다"],["목적","클라이언트의 삶의 질 향상을 위한 것이어야 한다"],["자료","개입에 필요한 자료를 수집하기 위한 도구가 될 수 있다 · 클라이언트에 관한 중요한 정보를 얻는 방법 중 하나이다"]]},{"t":"tree","title":"면접기술","root":"면접기술","branches":[["시선","클라이언트와 시선을 맞추어야 한다"],["표현 파악","클라이언트의 언어적ㆍ비언어적 표현을 함께 파악해야 한다 · 표정이나 몸짓도 관찰하여 의미를 파악한다"],["이해","클라이언트의 감정과 사고를 이해하고 파악하는 것이다 · 클라이언트의 사고와 감정을 이해하려는 적극적 활동이기도 하다"],["태도","클라이언트에 대한 열린 마음과 수용적인 태도가 필요하다"],["질문","클라이언트가 방어적인 태도를 취할 수 있기에 ‘왜’라는 질문은 피한다"]]}],"7":[{"t":"tree","title":"사정의 특성","root":"사정","branches":[["상호과정","클라이언트와 사회복지사 양자가 참여하는 상호과정이다 · 클라이언트의 참여가 필요하다"],["이중초점","환경 속의 클라이언트를 이해하고 계획의 근거를 마련하는 이중초점을 지닌다"],["개별화","클라이언트의 독특한 상황과 관련하여 개별화되어야 한다"],["강점","클라이언트의 강점을 포함해야 한다 · 문제와 욕구, 강점과 자원을 모두 포함한다"],["전 과정","실천의 전 과정을 통해 이루어진다"]]},{"t":"tree","title":"사정의 자료와 한계","root":"사정의 자료","branches":[["욕구 발견","클라이언트의 생활 속에서 욕구를 발견하고 문제를 정의한다"],["자료 수집","객관적인 자료뿐만 아니라 클라이언트의 주관적인 인식이 담긴 자료도 포함하여 수집한다"],["지식 근거","사회복지사의 지식적 근거가 필요하다 · 사회복지사와 클라이언트의 상호작용 과정이다"],["한계","클라이언트를 완전히 이해하는 것은 한계가 있다"]]}],"8":[{"t":"tree","title":"목표설정","root":"계획수립의 목표","branches":[["기관","계획의 목표는 기관의 기능과 일치해야 한다"],["변화 수준","미시적 수준과 거시적 수준에서 클라이언트의 변화를 고려한다"],["클라이언트","클라이언트가 원하는 결과를 포함하여 클라이언트의 적극적인 참여를 유도한다"],["합의","계획단계의 목표는 클라이언트와 사회복지사가 함께 합의하여 결정한다"]]}],"9":[{"t":"tree","title":"개입의 사례","root":"개입","branches":[["영유아","자신의 권리를 주장할 수 없는 영유아를 대변한다"],["무국적 아동","교육 평등권을 위한 법안을 제안한다"],["이주 노동자","최저 임금을 받을 권리를 교육한다"],["철거민","자체 회의를 위해 종합사회복지관의 공간을 제공한다"]]}],"11":[{"t":"cause","title":"클라이언트 욕구의 변화","causes":["복합적인 서비스를 필요로 하는 대상자가 증가하였다","인구ㆍ사회적 변화에 따라 다양하고, 복합적이며 만성적인 욕구를 가진 클라이언트가 증가하였다","탈 시설화로 인해 많은 정신 장애인이 지역사회 내에서 생활하게 되었다"],"result":"지역사회 내 서비스 간 조정이 필요하게 되었다","effects":[]},{"t":"cause","title":"복지 재정과 공급주체의 변화","causes":["복지국가 재정위기로 정책방향을 저비용ㆍ고효율로 전환하였다","복지비용 절감에 관심이 커지면서 저비용 고효율을 지향하게 되었다","서비스 공급주체가 중앙정부에서 지방정부로 변화하였다"],"result":"지역사회에서 서비스 조정이 필요하게 되었다","effects":[]}]};
