(window.TNQ=window.TNQ||[]).push({"terms":{"자선조직협회":{"d":"영국에서 민간 자선을 조정하고 우애방문과 조사를 한 단체로 개별사회사업의 뿌리입니다.","r":["적자생존","개별사회사업"]},"개별사회사업":{"d":"개인과 가족을 일대일로 만나 문제해결을 돕는 사회복지실천 방법입니다.","r":["자선조직협회"]},"적자생존":{"d":"환경에 맞는 개체만 살아남는다는 진화 논리로, 사회진화론이 빈곤에 적용했습니다.","r":["사회진화론"]},"평등권":{"d":"사회권에 해당하며 국가가 적극적으로 보장해야 하는 사회보장의 권리입니다.","r":[]},"자기결정권":{"d":"클라이언트가 자기 삶의 선택과 결정을 스스로 내릴 권리입니다.","r":[]},"수용":{"d":"클라이언트의 장점과 단점, 감정을 있는 그대로 받아들이는 전문적 관계의 원칙입니다.","r":[]},"이중초점":{"d":"개인과 환경, 그리고 둘의 상호작용을 함께 보는 사정의 관점입니다.","r":[]},"탈 시설화":{"d":"수용시설에서 지내던 사람들을 지역사회로 돌려보내 생활하게 하는 흐름입니다.","r":[]},"사회진화론":{"d":"생물의 적자생존 원리를 사회에 적용해 빈곤을 부적응의 결과로 보는 이론입니다.","r":["적자생존"]}},"notes":{"개인을 사회자원, 서비스, 기회를 제공해주는 환경체계와 연결한다":"개인이 필요한 자원과 기회를 얻도록 그것을 가진 주변 환경체계와 이어 주는 일입니다.","개인의 문제해결과 대처능력을 향상한다":"실천의 개인 차원 목적으로, 문제를 스스로 풀고 어려움에 맞서는 능력을 키우는 것입니다.","개입에 필요한 자료를 수집하기 위한 도구가 될 수 있다":"면접으로 개입 계획을 세울 때 쓸 자료를 모을 수 있습니다.","객관적인 자료뿐만 아니라 클라이언트의 주관적인 인식이 담긴 자료도 포함하여 수집한다":"검사 결과 같은 객관 자료와 본인이 느끼고 해석한 주관 자료를 함께 모읍니다.","거시적인 사회정책보다는 미시적인 사회사업 위주로 발전하게 하였다":"자선은 개인을 돕는 데 머물러 제도를 바꾸는 정책보다 개인 지원 위주로 자랐습니다.","경제적, 사회적, 문화적 권리이다":"평등권은 일할 권리, 사회보장, 교육 등 경제와 사회와 문화 영역의 권리를 아우릅니다.","경험과 역량을 가진 원조과정의 파트너로 본다":"클라이언트의 살아온 경험과 능력을 인정해 원조과정을 함께 이끄는 동반자로 대합니다.","계획단계의 목표는 클라이언트와 사회복지사가 함께 합의하여 결정한다":"목표를 한쪽이 정하면 실행되기 어려워 계획 단계에서 두 사람이 의견을 맞춰 정합니다.","계획의 목표는 기관의 기능과 일치해야 한다":"기관이 할 수 있는 서비스 범위를 벗어난 목표는 실행할 수 없으므로 기능과 맞아야 합니다.","과학적이고 적절한 자선활동을 수행하기 위해 클라이언트 등록체계를 실시하였다":"도움받는 사람을 등록해 중복 지원을 막고 조사 결과에 따라 필요한 지원을 정했습니다.","교육 평등권을 위한 법안을 제안한다":"국적이 없어 교육에서 불이익을 받는 아동을 위해 법과 제도를 바꾸려는 정책 차원의 개입입니다.","국가가 반드시 보호해 주어야 하는 권리이다":"자유권은 침해받지 않도록 국가가 반드시 지켜 주어야 하는 기본적인 권리입니다.","국가들 간의 연대와 단결의 권리이다":"평화권은 개인보다 국가와 민족이 서로 연대하여 평화를 누리는 집단적 권리에 속합니다.","국가의 적극적 책임과 의무를 강조하는 것으로 사회보장의 권리를 의미한다":"평등권은 국가가 나서서 생활을 보장해야 한다는 점에서 사회보장을 요구할 권리가 됩니다.","국가의 통치와 간섭으로부터 자유를 보장하기 위한 권리이다":"자유권은 국가가 개인의 생활에 함부로 개입하지 못하도록 막는 소극적 성격을 가집니다.","다양한 사회복지기관이나 조직의 효과적이고 효율적인 운영을 촉진한다":"기관이 목표를 이루고 자원을 덜 낭비하며 돌아가도록 돕는 것도 실천의 목적에 듭니다.","모든 클라이언트는 강점이 있다고 본다":"문제가 있는 사람이라도 활용할 만한 강점이 있다고 여기고 그것에서 출발합니다.","문제와 욕구, 강점과 자원을 모두 포함한다":"사정은 어려움과 필요뿐 아니라 활용 가능한 강점과 자원까지 두루 담아 균형을 맞춥니다.","미시적 수준과 거시적 수준에서 클라이언트의 변화를 고려한다":"개인이나 가족 수준의 변화뿐 아니라 지역사회와 제도 수준의 변화도 함께 목표로 삼습니다.","민간 사회복지기관의 활동을 체계적으로 조정하기 위해 등장하였다":"여러 민간 기관이 같은 사람을 중복해 돕는 일이 잦아 활동을 조정하려는 목적으로 생겼습니다.","법원 명령으로 본인 의사와 관계없이 문제행동 감소를 위해 사회복지사에게 의뢰된 청소년":"자발적으로 온 것이 아니라 법원이 의뢰했고 행동 변화를 겨냥하므로 청소년은 표적체계입니다.","복지국가 재정위기로 정책방향을 저비용ㆍ고효율로 전환하였다":"복지국가의 재정이 부족해지자 적은 비용으로 높은 성과를 내는 쪽으로 정책을 바꿨습니다.","복지비용 절감에 관심이 커지면서 저비용 고효율을 지향하게 되었다":"비용을 줄이려는 요구가 커지니 서비스도 비용 대비 효과를 따지는 방식으로 운영됩니다.","복합적인 서비스를 필요로 하는 대상자가 증가하였다":"한 가지 서비스로는 해결되지 않고 여러 분야의 도움이 한꺼번에 필요한 사람이 늘었습니다.","부모가 자녀의 문제로 상담을 요청한 경우, 부모":"자녀 문제로 부모가 상담을 신청했다면 서비스를 요청한 사람이니 부모가 클라이언트체계입니다.","사람들이 사회복지를 구호사업 또는 자선사업과 같은 것으로 인식하게 하였다":"그 영향으로 오늘날에도 사회복지를 시혜적인 도움으로 여기는 시각이 남아 있습니다.","사회복지가 종교와 밀접한 관련 하에 전개되도록 하였다":"초기 구제 활동은 교회와 종교 단체가 이끌어서 사회복지가 종교와 함께 발전했습니다.","사회복지사는 소속된 기관의 특성에 영향을 받는다":"기관의 목적과 정책, 자원에 따라 사회복지사가 할 수 있는 일의 범위가 달라집니다.","사회복지사는 전문성에 바탕을 둔 권위를 가진다":"이 권위는 직위가 아니라 지식과 기술 같은 전문성에서 나오는 것입니다.","사회복지사와 클라이언트가 합의하여 목적을 설정한다":"전문적 관계의 목적은 사회복지사 혼자 세우지 않고 클라이언트와 합의해 정합니다.","사회복지사와 클라이언트 사이의 특정한 역할 관계가 있다":"면접은 일상 대화와 달리 도우는 사람과 도움받는 사람이라는 정해진 역할 위에서 이뤄집니다.","사회복지사와 클라이언트의 상호작용 과정이다":"사정에서 얻는 정보는 두 사람이 서로 영향을 주고받는 과정 속에서 만들어집니다.","사회복지사의 지식적 근거가 필요하다":"모은 자료를 해석하고 문제를 규정하려면 사회복지사가 이론과 지식에 근거해야 합니다.","사회복지사의 활동 목적을 달성하기 위해 공동으로 노력하는 모든 체계":"사회복지사와 함께 목적을 이루려고 움직이는 모든 사람과 조직이 행동체계에 속합니다.","사회정책의 개발과 향상에 기여한다":"현장에서 확인된 문제를 바탕으로 사회정책이 만들어지고 나아지게 하는 것이 실천 목적입니다.","서비스 공급주체가 중앙정부에서 지방정부로 변화하였다":"서비스를 책임지는 쪽이 중앙에서 지역 사정을 잘 아는 지방정부로 옮겨 갔습니다.","서비스에 대한 권리를 가진 소비자로 본다":"클라이언트는 도움을 받는 수혜자가 아니라 서비스를 요구할 권리가 있는 소비자입니다.","실천의 전 과정을 통해 이루어진다":"사정은 초기에 한 번 끝나지 않고 새 정보가 나올 때마다 이어지며 개입 중에도 다듬어집니다.","어떤 환경이든 자원은 존재한다고 본다":"강점관점은 열악해 보이는 환경에도 활용할 수 있는 자원이 반드시 있다고 전제합니다.","인간이 세상에 태어나면서부터 존엄성을 가지고 태어났다는 의미이다":"인권은 국가가 주는 것이 아니라 출생과 동시에 가지는 존엄성에서 나온다는 뜻입니다.","인구ㆍ사회적 변화에 따라 다양하고, 복합적이며 만성적인 욕구를 가진 클라이언트가 증가하였다":"고령화 같은 변화로 욕구가 다양하게 겹치고 오래 지속되는 클라이언트가 많아졌습니다.","자선조직협회 활동은 개별사회사업의 초석이 되었다":"우애방문원이 가정을 방문해 조사하고 상담한 경험이 쌓여 개별사회사업의 기초가 됐습니다.","자신의 권리를 주장할 수 없는 영유아를 대변한다":"영유아는 스스로 요구하지 못하므로 사회복지사가 대신 말하는 옹호 역할을 맡습니다.","자체 회의를 위해 종합사회복지관의 공간을 제공한다":"철거민이 스스로 모여 논의할 수 있도록 복지관이 장소라는 자원을 내어 주는 개입입니다.","적자생존에 기반한 사회진화론을 구빈의 이론적 기반으로 삼았다":"가난은 환경에 적응하지 못한 개인 탓이라는 생각에서 빈민 구제를 선별하는 근거를 얻었습니다.","전문 사회복지의 시작을 촉발하였다":"종교적 자선이 체계를 갖추며 전문 직업으로서의 사회복지가 비롯되는 계기가 됐습니다.","지역사회 내 서비스 간 조정이 필요하게 되었다":"서비스가 여러 곳에 흩어져 있어 이용자가 불편하지 않도록 서비스끼리 연결하고 조정해야 합니다.","지역사회에서 서비스 조정이 필요하게 되었다":"공급 주체가 지방정부로 나뉘면서 지역 안의 기관들이 서비스를 서로 맞춰야 하는 일이 생겼습니다.","최저 임금을 받을 권리를 교육한다":"이주 노동자가 자기 권리를 알고 주장할 수 있도록 정보를 알려 주는 교육자 역할의 개입입니다.","클라이언트가 방어적인 태도를 취할 수 있기에 ‘왜’라는 질문은 피한다":"왜냐고 물으면 추궁처럼 들려 방어적으로 변하기 쉬워 무엇과 어떻게로 바꿔 묻습니다.","클라이언트가 안도감을 갖게 하여 현실적인 방법으로 문제 대처를 할 수 있도록 돕는다":"받아들여졌다는 안도감이 생기면 클라이언트가 침착하게 현실적인 대처 방법을 찾습니다.","클라이언트가 원하는 결과를 포함하여 클라이언트의 적극적인 참여를 유도한다":"클라이언트가 바라는 결과를 목표에 넣으면 자기 목표라고 느껴 더 적극적으로 참여합니다.","클라이언트가 원하는 변화를 위해 양자 간 협력적 관계를 형성한다":"임파워먼트에서는 사회복지사가 지시하지 않고 클라이언트와 동등하게 협력합니다.","클라이언트를 선택과 결정의 주체로 본다":"사회복지사가 대신 정하지 않고 클라이언트가 직접 고르고 결정하게 합니다.","클라이언트를 완전히 이해하는 것은 한계가 있다":"사람의 삶은 복잡하고 자료도 제한적이라 사정으로 클라이언트를 전부 알 수는 없습니다.","클라이언트를 있는 그대로 이해한다":"수용은 좋고 나쁨을 따지지 않고 클라이언트의 모습과 처지를 있는 그대로 알아주는 것입니다.","클라이언트에 관한 중요한 정보를 얻는 방법 중 하나이다":"면접은 클라이언트의 상황과 욕구에 대한 핵심 정보를 직접 얻는 길의 하나입니다.","클라이언트에 대한 열린 마음과 수용적인 태도가 필요하다":"선입견 없이 열린 마음으로 받아들여야 클라이언트가 편하게 속마음을 말합니다.","클라이언트와 사회복지사 양자가 참여하는 상호과정이다":"사정은 사회복지사 혼자 하는 판단이 아니라 클라이언트와 주고받으며 만들어 가는 과정입니다.","클라이언트와 시선을 맞추어야 한다":"눈을 맞추면 관심을 두고 듣고 있다는 신호가 되어 클라이언트가 말을 이어 가기 쉽습니다.","클라이언트의 감정과 사고를 이해하고 파악하는 것이다":"경청은 들리는 말만이 아니라 그 안의 감정과 생각까지 이해하는 일입니다.","클라이언트의 강점을 포함해야 한다":"문제만 보면 해결 자원을 놓치므로 사정에는 클라이언트가 가진 강점도 담아야 합니다.","클라이언트의 독특한 상황과 관련하여 개별화되어야 한다":"같은 문제라도 사람마다 처지가 달라서 사정은 그 사람의 고유한 상황에 맞춰 이뤄집니다.","클라이언트의 문제를 해결하기 위해 노력하는 사회복지사와 사회복지기관":"변화를 일으키려는 일꾼 쪽, 곧 사회복지사와 기관 전체가 변화매개체계입니다.","클라이언트의 문제와 욕구가 중심이 된다":"전문적 관계에서는 사회복지사의 필요가 아니라 클라이언트가 겪는 문제와 욕구가 기준입니다.","클라이언트의 부정적인 감정도 받아들인다":"분노나 불안 같은 감정도 비난하지 않고 받아 주는 태도가 수용에 포함됩니다.","클라이언트의 사고와 감정을 이해하려는 적극적 활동이기도 하다":"듣는 일은 가만히 있는 것이 아니라 상대 생각과 감정을 알아내려고 애쓰는 능동적 행위입니다.","클라이언트의 삶의 질 향상을 위한 것이어야 한다":"면접은 클라이언트의 삶이 나아지는 데 쓰여야 하며 사회복지사의 호기심 충족이 아닙니다.","클라이언트의 생활 속에서 욕구를 발견하고 문제를 정의한다":"일상 속 사정을 들여다보며 무엇이 부족한지 찾고 해결할 문제로 규정합니다.","클라이언트의 언어적ㆍ비언어적 표현을 함께 파악해야 한다":"말로 한 내용과 표정, 목소리처럼 말 이외의 표현이 서로 다를 수 있으므로 함께 읽습니다.","클라이언트의 참여가 필요하다":"자기 상황을 가장 잘 아는 사람이 클라이언트이므로 사정에는 그의 참여가 빠질 수 없습니다.","클라이언트의 참여를 중시하고 자기결정권을 강조한다":"문제 해결 과정에 클라이언트가 직접 참여하고 스스로 결정하는 것이 중심입니다.","탈 시설화로 인해 많은 정신 장애인이 지역사회 내에서 생활하게 되었다":"정신 장애인이 시설에서 나와 지역에 살게 되면서 지역사회에서의 지원이 필요해졌습니다.","특정 상황이나 맥락에 관련하여 이루어진다":"면접은 기관의 기능이나 클라이언트가 처한 상황 같은 구체적 맥락 속에서 진행됩니다.","편견이나 선입관을 줄여나가면 수용에 도움이 된다":"미리 가진 판단이 있으면 상대를 있는 그대로 보기 어렵기 때문에 이를 줄여야 합니다.","표정이나 몸짓도 관찰하여 의미를 파악한다":"말로 드러나지 않는 감정이 표정과 몸짓에 담기므로 이를 관찰해 뜻을 읽어 냅니다.","환경 속의 클라이언트를 이해하고 계획의 근거를 마련하는 이중초점을 지닌다":"사정은 사람과 환경을 함께 이해하는 동시에 개입 계획을 세울 근거를 마련하는 두 가지 초점을 가집니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
